use xiom.io;

use xiom.string;
fn to_roman(n: Int) -> Str {
  let values: Vec[Int] = Vec[Int].new();
  values.push(1000); values.push(900); values.push(500); values.push(400);
  values.push(100); values.push(90); values.push(50); values.push(40);
  values.push(10); values.push(9); values.push(5); values.push(4); values.push(1);

  let symbols: Vec[Str] = Vec[Str].new();
  symbols.push("M"); symbols.push("CM"); symbols.push("D"); symbols.push("CD");
  symbols.push("C"); symbols.push("XC"); symbols.push("L"); symbols.push("XL");
  symbols.push("X"); symbols.push("IX"); symbols.push("V"); symbols.push("IV");
  symbols.push("I");

  let mut result = "";
  let mut num = n;
  let mut i = 0;
  while i < values.len() {
    while num >= values.get(i).unwrap() {
      result = string.str_concat(result, symbols.get(i).unwrap());
      num -= values.get(i).unwrap();
    };
    i += 1;
  };
  result
}

fn main() -> Int {
  io.println(to_roman(2024));
  io.println(to_roman(58));
  io.println(to_roman(1999));
  return 0;
}
